package com.gameaggregator.webhookservice.api;import com.gameaggregator.platform.core.common.web.ApiResponse;import com.gameaggregator.webhookservice.application.WebhookService;import com.gameaggregator.webhookservice.domain.*;import jakarta.validation.Valid;import java.util.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/webhooks") public class WebhookController{final WebhookService s;public WebhookController(WebhookService s){this.s=s;}@PostMapping ApiResponse<WebhookDtos.Issued> create(@Valid @RequestBody WebhookDtos.Create r){return ApiResponse.success(s.create(r));}@GetMapping ApiResponse<List<WebhookEndpoint>> list(){return ApiResponse.success(s.list());}@PatchMapping("/{id}/status")ApiResponse<WebhookEndpoint> status(@PathVariable UUID id,@RequestBody WebhookDtos.Status r){return ApiResponse.success(s.status(id,r));}@GetMapping("/{id}/deliveries")ApiResponse<List<WebhookDelivery>> deliveries(@PathVariable UUID id){return ApiResponse.success(s.deliveries(id));}@PostMapping("/deliveries/{id}/replay")ApiResponse<WebhookDelivery> replay(@PathVariable UUID id){return ApiResponse.success(s.replay(id));}}